const input = $input.first().json;

const logEntry = {
  request_id: input.request_id || $execution.id,
  timestamp: new Date().toISOString(),
  client: input.client || 'unknown',
  api: input.api || 'unknown',
  action: input.action || 'unknown',
  status: input.status || 'unknown',
  duration_ms: input.duration_ms || 0,
  error: input.error || null,
  metadata: {
    workflow_id: $workflow.id,
    execution_id: $execution.id
  }
};

return [{ json: logEntry }];

const logEntry = $input.first().json;

// In production, this would write to an n8n data table, database, or external logging service
// such as Elasticsearch, Datadog, or a similar observability platform.
// For MVP, we log to console and pass through the structured entry.

const storedLog = {
  ...logEntry,
  stored: true,
  storage_backend: 'console',
  stored_at: new Date().toISOString()
};

console.log(`[REQUEST_LOG] ${JSON.stringify(storedLog)}`);

return [{ json: storedLog }];

const storedLog = $input.first().json;

return [{
  json: {
    success: true,
    request_id: storedLog.request_id,
    logged_at: storedLog.stored_at,
    message: 'Request logged successfully'
  }
}];
